-- P6-IAM-001：人工维护，依据已批准 V1.3；仅适用于经确认的全新空库。
-- MySQL 8.0.17+（基线 8.0.44），严格 SQL 模式；执行前审核目标库、权限及授权。
-- 顺序：组织、用户、关联、触发器；不创建数据库，不写业务种子。
CREATE TABLE sys_organization (
    id CHAR(32) NOT NULL,
    organization_code VARCHAR(64) NOT NULL,
    organization_name VARCHAR(200) NOT NULL,
    organization_type VARCHAR(32) NOT NULL,
    parent_id CHAR(32) NULL,
    status VARCHAR(8) NOT NULL DEFAULT 'active',
    is_deleted BOOLEAN NOT NULL DEFAULT 0,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    active_key TINYINT GENERATED ALWAYS AS (CASE WHEN is_deleted=0 THEN 1 ELSE NULL END) VIRTUAL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_sys_organization_code_active (organization_code, active_key),
    KEY ix_sys_org_parent_deleted_status (parent_id, is_deleted, status),
    CONSTRAINT fk_sys_org_parent FOREIGN KEY (parent_id) REFERENCES sys_organization(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT ck_sys_organization_deleted CHECK (is_deleted IN (0,1)),
    CONSTRAINT ck_sys_organization_type_and_text CHECK (organization_type IN ('group','company','department') AND ((organization_code IS NOT NULL AND CHAR_LENGTH(organization_code) > 0 AND NOT REGEXP_LIKE(organization_code, CONVERT(X'' USING utf8mb4), 'c')) AND NOT REGEXP_LIKE(organization_code, CONVERT(X'5b5c787b303030397d2d5c787b303030447d5c787b303031437d2d5c787b303032307d5c787b303038357d5c787b303041307d5c787b313638307d5c787b323030307d2d5c787b323030417d5c787b323032387d5c787b323032397d5c787b323032467d5c787b323035467d5c787b333030307d5d' USING utf8mb4), 'c')) AND (organization_name IS NOT NULL AND CHAR_LENGTH(organization_name) > 0 AND NOT REGEXP_LIKE(organization_name, CONVERT(X'' USING utf8mb4), 'c'))),
    CONSTRAINT ck_sys_organization_not_self CHECK (parent_id IS NULL OR parent_id <> id),
    CONSTRAINT ck_sys_organization_root CHECK ((organization_type='group' AND parent_id IS NULL) OR organization_type='company' OR (organization_type='department' AND parent_id IS NOT NULL)),
    CONSTRAINT ck_sys_organization_record_status CHECK (status IN ('active', 'inactive'))
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE sys_user (
    id CHAR(32) NOT NULL,
    username VARCHAR(64) NOT NULL,
    real_name VARCHAR(100) NOT NULL,
    nickname VARCHAR(100) NULL,
    display_name VARCHAR(100) NULL,
    email VARCHAR(254) NULL,
    phone VARCHAR(16) NULL,
    password_hash VARCHAR(512) NULL,
    status VARCHAR(8) NOT NULL DEFAULT 'inactive',
    is_deleted BOOLEAN NOT NULL DEFAULT 0,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    invitation_token_hash CHAR(64) NULL,
    invitation_issued_at DATETIME(6) NULL,
    invitation_expires_at DATETIME(6) NULL,
    invitation_sent_at DATETIME(6) NULL,
    invitation_accepted_at DATETIME(6) NULL,
    invitation_revoked_at DATETIME(6) NULL,
    active_key TINYINT GENERATED ALWAYS AS (CASE WHEN is_deleted=0 THEN 1 ELSE NULL END) VIRTUAL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_sys_user_username_active (username, active_key),
    UNIQUE KEY uq_sys_user_email_active (email, active_key),
    UNIQUE KEY uq_sys_user_phone_active (phone, active_key),
    UNIQUE KEY uq_sys_user_invitation_hash (invitation_token_hash),
    KEY ix_sys_user_deleted_status (is_deleted, status),
    CONSTRAINT ck_sys_user_deleted CHECK (is_deleted IN (0,1)),
    CONSTRAINT ck_sys_user_required_text CHECK (((username IS NOT NULL AND CHAR_LENGTH(username) > 0 AND NOT REGEXP_LIKE(username, CONVERT(X'' USING utf8mb4), 'c')) AND NOT REGEXP_LIKE(username, CONVERT(X'5b5c787b303030397d2d5c787b303030447d5c787b303031437d2d5c787b303032307d5c787b303038357d5c787b303041307d5c787b313638307d5c787b323030307d2d5c787b323030417d5c787b323032387d5c787b323032397d5c787b323032467d5c787b323035467d5c787b333030307d5d' USING utf8mb4), 'c')) AND (real_name IS NOT NULL AND CHAR_LENGTH(real_name) > 0 AND NOT REGEXP_LIKE(real_name, CONVERT(X'' USING utf8mb4), 'c'))),
    CONSTRAINT ck_sys_user_optional_text CHECK ((nickname IS NULL OR (nickname IS NOT NULL AND CHAR_LENGTH(nickname) > 0 AND NOT REGEXP_LIKE(nickname, CONVERT(X'' USING utf8mb4), 'c'))) AND (display_name IS NULL OR (display_name IS NOT NULL AND CHAR_LENGTH(display_name) > 0 AND NOT REGEXP_LIKE(display_name, CONVERT(X'' USING utf8mb4), 'c'))) AND (email IS NULL OR (((email IS NOT NULL AND CHAR_LENGTH(email) > 0 AND NOT REGEXP_LIKE(email, CONVERT(X'' USING utf8mb4), 'c')) AND NOT REGEXP_LIKE(email, CONVERT(X'5b5e212d7e5d' USING utf8mb4), 'c')) AND email = LOWER(email) COLLATE utf8mb4_0900_bin AND CHAR_LENGTH(email) - CHAR_LENGTH(REPLACE(email, '@', '')) = 1 AND LEFT(email, 1) <> '@' AND RIGHT(email, 1) <> '@')) AND (phone IS NULL OR ((phone IS NOT NULL AND CHAR_LENGTH(phone) > 0 AND NOT REGEXP_LIKE(phone, CONVERT(X'' USING utf8mb4), 'c')) AND REGEXP_LIKE(phone, CONVERT(X'5e5b2b5d5b312d395d5b302d395d7b302c31347d24' USING utf8mb4), 'c'))) AND (password_hash IS NULL OR (CHAR_LENGTH(password_hash) BETWEEN 1 AND 512 AND ((password_hash IS NOT NULL AND CHAR_LENGTH(password_hash) > 0 AND NOT REGEXP_LIKE(password_hash, CONVERT(X'' USING utf8mb4), 'c')) AND NOT REGEXP_LIKE(password_hash, CONVERT(X'5b5e212d7e5d' USING utf8mb4), 'c'))))),
    CONSTRAINT ck_sys_user_status CHECK (status IN ('active','inactive','locked')),
    CONSTRAINT ck_sys_user_activation CHECK ((status <> 'active' OR password_hash IS NOT NULL) AND (invitation_accepted_at IS NULL OR password_hash IS NOT NULL)),
    CONSTRAINT ck_sys_user_invitation CHECK (((invitation_issued_at IS NULL AND invitation_token_hash IS NULL
  AND invitation_expires_at IS NULL AND invitation_sent_at IS NULL
  AND invitation_accepted_at IS NULL AND invitation_revoked_at IS NULL)
 OR (invitation_issued_at IS NOT NULL AND invitation_expires_at IS NOT NULL
  AND invitation_expires_at > invitation_issued_at
  AND (invitation_sent_at IS NULL OR invitation_sent_at >= invitation_issued_at)
  AND (invitation_accepted_at IS NULL OR
       (invitation_accepted_at >= invitation_issued_at
        AND invitation_accepted_at < invitation_expires_at))
  AND (invitation_revoked_at IS NULL OR invitation_revoked_at >= invitation_issued_at)
  AND (invitation_accepted_at IS NULL OR invitation_revoked_at IS NULL)
  AND ((invitation_accepted_at IS NULL AND invitation_revoked_at IS NULL)
       OR invitation_token_hash IS NULL)
  AND (invitation_accepted_at IS NOT NULL OR invitation_revoked_at IS NOT NULL
       OR is_deleted = 1 OR invitation_token_hash IS NOT NULL)))
 AND (invitation_token_hash IS NULL OR (CHAR_LENGTH(invitation_token_hash) = 64 AND NOT REGEXP_LIKE(invitation_token_hash, CONVERT(X'5b5e302d39612d665d' USING utf8mb4), 'c'))))
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

CREATE TABLE sys_user_organization (
    id CHAR(32) NOT NULL,
    user_id CHAR(32) NOT NULL,
    organization_id CHAR(32) NOT NULL,
    is_primary BOOLEAN NOT NULL DEFAULT 0,
    is_deleted BOOLEAN NOT NULL DEFAULT 0,
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    active_key TINYINT GENERATED ALWAYS AS (CASE WHEN is_deleted=0 THEN 1 ELSE NULL END) VIRTUAL,
    primary_user_id CHAR(32) GENERATED ALWAYS AS (CASE WHEN is_deleted=0 AND is_primary=1 THEN user_id ELSE NULL END) VIRTUAL,
    PRIMARY KEY (id),
    UNIQUE KEY uq_sys_user_org_active (user_id, organization_id, active_key),
    UNIQUE KEY uq_sys_user_org_primary (primary_user_id),
    KEY ix_sys_user_org_user_deleted_primary (user_id, is_deleted, is_primary),
    KEY ix_sys_user_org_org_deleted_user (organization_id, is_deleted, user_id),
    CONSTRAINT fk_sys_user_org_user FOREIGN KEY (user_id) REFERENCES sys_user(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT fk_sys_user_org_org FOREIGN KEY (organization_id) REFERENCES sys_organization(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    CONSTRAINT ck_sys_user_organization_flags CHECK (is_deleted IN (0,1) AND is_primary IN (0,1))
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_bin;

DELIMITER $$
CREATE TRIGGER trg_sys_organization_before_update
BEFORE UPDATE ON sys_organization FOR EACH ROW
BEGIN
    IF OLD.is_deleted=1 AND NEW.is_deleted=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Deleted organization cannot be restored';
    END IF;
    IF NOT (OLD.id <=> NEW.id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Organization id is immutable';
    END IF;
END$$
CREATE TRIGGER trg_sys_user_before_update
BEFORE UPDATE ON sys_user FOR EACH ROW
BEGIN
    IF OLD.is_deleted=1 AND NEW.is_deleted=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Deleted user cannot be restored';
    END IF;
    IF NOT (OLD.id <=> NEW.id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='User id is immutable';
    END IF;
END$$
CREATE TRIGGER trg_sys_user_organization_before_update
BEFORE UPDATE ON sys_user_organization FOR EACH ROW
BEGIN
    IF OLD.is_deleted=1 AND NEW.is_deleted=0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Deleted membership cannot be restored';
    END IF;
    IF NOT (OLD.id <=> NEW.id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Membership id is immutable';
    END IF;
END$$
DELIMITER ;
